function offlineApplyMemoryTags(text,c,userText,outcome){let changed=false;const full=lifeNoteStripModelTags(text),out=full.replace(/[\[【]\s*记住\s*[|｜:：]\s*([^\]】]+)[\]】]/g,(all,tx)=>{const r=rememberFromConversation(c,tx,userText,full,{rolePerspective:true}),ok=r==='added'||r==='replaced'||r==='confirmed'||r==='conflict';if(ok)changed=true;roleInterceptDiagnosticAction(outcome,ok);return '';});if(changed)save();return{text:out,changed};}
