  s+=offlineLifeNotesPrompt(c,query)+roleOwnMomentsPrompt(c,6)+roleVisibleUserMomentsPrompt(c,6)+offlineBehaviorLedgerPrompt(c)+dialogueEmotionPrompt(c)+memoryCriticalPrompt(c)+cohabPhonePrompt(c)+cohabTripContext(c,o);
  s+=offlineMemoryRule(c);
