function offSummaryPlan(msgs){const rows=(msgs||[]).filter(m=>m&&m.who!=='日期'&&String(m.text||'').trim()),chars=rows.reduce((n,m)=>n+Array.from(String(m.text||'')).length,0),actions=rows.filter(m=>m.who==='旁白').length,n=rows.length;let level,min,max,keep,tokens,minPoints,maxPoints;if(n<=8&&chars<=500){level='简短';min=120;max=260;keep=360;tokens=900;minPoints=2;maxPoints=3;}else if(n<=24&&chars<=1800){level='适中';min=300;max=620;keep=760;tokens=1400;minPoints=3;maxPoints=6;}else if(n<=60&&chars<=5000){level='详细';min=600;max=1200;keep=1400;tokens=2200;minPoints=5;maxPoints=9;}else{level='完整长篇';min=1000;max=2200;keep=2400;tokens=3200;minPoints=8;maxPoints=12;}return{level,min,max,keep,tokens,minPoints,maxPoints,rows:n,chars,actions};}
