function offSummaryUserCall(c){return String(c&&c.callme||S.me.name||'ta').trim()||'ta';}
function offSummaryPerspectiveRule(c){const call=offSummaryUserCall(c);return'\n【记忆视角硬规则】必须站在角色自己的角度，用“我”指角色本人，用角色平时对'+call+'的称呼指对方。禁止写成第三人称旁白、剧本梗概、镜头描述或“他/她做了什么”的动作流水账；普通走路、坐下、起身、拿东西、姿势、衣着和环境描写全部省略。动作只有确实引发重要事件、明确承诺、情绪转折或关系变化时，才能把它造成的意义改写成第一人称记忆，不能照抄旁白原句。';}
function offSummaryMemoryPerspectiveValid(text){text=String(text||'');return text.includes('我')&&!/旁白|剧本|动作描写|镜头描述|镜头里/.test(text);}
