function offCreateWechatHandoff(c,ended){const rows=offSummarySourceRows(ended),limit=Math.max(10,Math.min(80,+(S.settings&&S.settings.offHist)||30)),picked=[],maxChars=14000,endedAt=Date.now();let chars=0;for(let i=rows.length-1;i>=Math.max(0,rows.length-limit);i--){const line='['+(i+1)+'] '+offSummarySourceWho(rows[i],c)+'：'+String(rows[i].text||'').replace(/\s+/g,' ').trim().slice(0,700);if(picked.length&&chars+line.length>maxChars)break;picked.unshift(line);chars+=line.length;}return{session:ended.session||'',ts:endedAt,endedAt,expiresAt:endedAt+12*3600000,turns:3,count:picked.length,loc:ended.loc||'',when:ended.when||'',daypart:ended.daypart||'',text:picked.join('\n')};}
