function offEndReplyMatches(info,content){if(!info)return false;const x=String(content||'').replace(/[\s\n]+/g,' ').trim();if(!x)return false;if(/(?:一整天|半天|这么久|那么久|一直|到现在).{0,12}(?:没回|不回|没理|不理)|(?:怎么|为什么|干嘛).{0,10}(?:没回|不回|没理|不理)|(?:失踪|消失).{0,12}(?:一天|半天|这么久|那么久)/.test(x))return false;return /(?:刚才|刚刚|见面|约会|分开|告别|到家|回去|回程|路上|送你|舍不得|想你|下次|今晚|今天见)/.test(x);}
