function offWechatHandoffPrompt(c,query){const h=c&&c._offlineHandoff,explicit=offHandoffRecallQuery(query),active=h&&h.turns>0&&Date.now()<=(h.expiresAt||0),recent=h&&Date.now()-(h.ts||0)<=30*86400000;if(!h||!h.text||(!active&&!(explicit&&recent)))return'';const strict=explicit?'\n【用户正在核对约会结尾】只能依据上面的逐条原文回答“最后说了什么/发生了什么”。原文没有的台词、动作、承诺和称呼一律不能猜；若原文不足以回答，就如实说自己不确定具体原话，绝不能为了显得记得而编造。':'';return '\n\n# 刚结束的线下约会末段（微信隐藏承接上下文·优先级很高）\n这场约会已经结束，你们现在回到微信。地点：'+(h.loc||'原约会地点')+'；时间：'+(h.when||'刚才')+(h.daypart?'；时段：'+h.daypart:'')+'。下面是按“线下约会→上下文条数”设置带入的最后 '+h.count+' 条真实原始记录，按发生顺序排列：\n'+h.text+'\n必须记得最后发生了什么、谁说了什么、最后怎样分开，再用普通微信文字自然承接；不要回复更早的旧问题，不要把过去式继续演成仍在现场，不要输出旁白【】、编号、系统提示或整段复述这些记录。'+strict;}
function offLastEndedPrompt(c){const x=c&&c._lastOfflineEnded,age=x&&Date.now()-(+x.endedAt||0);if(!x||age<0||age>7*86400000)return'';return '\n\n# 最近一次一次性线下约会已结束（持续事实）\n你和'+S.me.name+'最近一次在「'+(x.loc||'原约会地点')+'」的线下见面已经于【'+fmtDT(x.endedAt)+'】结束，当前已回到线上；这不是共同生活，也不是仍待赴约的邀请。除非结束之后又有一条明确的新约会邀请并已约定成功，否则绝不能把这同一场见面说成“马上去见你、等会儿见、还没见到”。可以把刚见过当成真实过去经历，自然聊分别后、回程或下一次另约。';}
