function offSummaryInstruction(c,ended,plan,repair,part,total){const call=offSummaryUserCall(c),segment=total>1?'这是完整约会的第'+part+'/'+total+'段，必须把这一段独有的重点整理出来，不要因为还没看到其他段就省略。\n':'';return '你就是「'+(c.remark||c.name)+'」本人，要把带编号的线下约会原记录整理成完整、可长期记住的重点。'+segment+'本段需要【'+plan.minPoints+'~'+plan.maxPoints+'条】，按原文发生顺序输出。'+(repair?'\n上一版漏选、少于100字或不完整，请从头重新检查这一段，尤其检查最后几条。':'')+'\n必须覆盖：真正重要的事件；双方重要问答；'+call+'透露的重要经历、家庭、秘密、偏好和计划；承诺、保证、约定、以后怎么做和下一次安排；关系确认或变化；争执、误会、道歉、和好和情绪转折；最后如何结束。最后几条里的重要决定必须总结，不能只写中间。普通寒暄、重复撒娇、场景铺陈和无关动作全部省略。\n每条text必须写成【100~260个中文字】的第一人称完整记忆，要交代事情的起因、双方关键话语、结果及它对当时关系的实际变化；禁止十几个字的短句。每个事实都必须能被sourceIndexes里的原文直接证明，不能补写原文没有的情绪、原因、承诺、关系或后续。sourceIndexes填1~6个原文编号；importance为1~5。'+offSummaryPerspectiveRule(c)+'\n只输出JSON数组：[{'+'"text":"至少100字的完整第一人称记忆","sourceIndexes":[3,4],"importance":4}]。不要Markdown、解释、标题，也不要提AI或规则。';}
function offSummaryTooThin(text,plan){const n=Array.from(String(text||'').replace(/\s+/g,'')).length;return n<Math.max(45,Math.floor(plan.min*.45));}
function offSummaryChunks(text,limit){limit=Math.max(2200,+limit||6000);const lines=String(text||'').split('\n').filter(x=>x.trim()),out=[];let cur='';for(let line of lines){while(line.length>limit){if(cur){out.push(cur);cur='';}out.push(line.slice(0,limit));line=line.slice(limit);}if(!line)continue;if(cur&&cur.length+line.length+1>limit){out.push(cur);cur=line;}else cur+=(cur?'\n':'')+line;}if(cur)out.push(cur);return out;}
